srcDoc.css:
html, body { margin: 0; height: 100%; background: #0F172A; }

.wrap {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  font-family: system-ui, -apple-system, sans-serif;
  color: #E2E8F0;
}

/* --- saved-report toolbar --------------------------------------------------- */
.bar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  background: #1E293B;
  border-bottom: 1px solid #334155;
}
.bar-left { display: flex; align-items: baseline; gap: 8px; min-width: 0; flex: 1 1 auto; }
.bar-right { display: flex; align-items: center; gap: 6px; flex: 0 0 auto; }
.rep-label { font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: #64748B; }
.rep-name { font-size: 14px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 40%; }
.rep-name.unsaved { color: #94A3B8; font-weight: 500; font-style: italic; }
.rep-dirty { font-size: 12px; color: #E5B562; white-space: nowrap; }
.rep-meta { font-size: 12px; color: #94A3B8; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rep-busy { font-size: 12px; color: #93C5FD; white-space: nowrap; }
.count { color: #94A3B8; }

.btn {
  font: inherit;
  font-size: 13px;
  line-height: 1;
  padding: 7px 11px;
  border-radius: 6px;
  border: 1px solid #334155;
  background: #243244;
  color: #E2E8F0;
  cursor: pointer;
  white-space: nowrap;
}
.btn:hover:not(:disabled) { background: #334155; }
.btn:disabled { opacity: .45; cursor: default; }
.btn.primary { background: #3B82F6; border-color: #3B82F6; color: #fff; }
.btn.primary:hover:not(:disabled) { background: #2563EB; }
.btn.danger { background: #7F1D1D; border-color: #B91C1C; color: #FEE2E2; }
.btn.danger:hover:not(:disabled) { background: #991B1B; }
.btn.small { font-size: 12px; padding: 5px 8px; }

input[type=text] {
  font: inherit;
  font-size: 13px;
  padding: 6px 8px;
  border-radius: 6px;
  border: 1px solid #334155;
  background: #0F172A;
  color: #E2E8F0;
  outline: none;
  box-sizing: border-box;
}
input[type=text]:focus { border-color: #3B82F6; }

/* name form and confirmation, shown under the toolbar */
.strip {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  background: #172033;
  border-bottom: 1px solid #334155;
  font-size: 13px;
}
.strip[hidden] { display: none; }
.strip label { color: #CBD5E1; }
.strip #name-input { width: 320px; max-width: 45%; }
.strip.warn { background: #3B2E1A; }
.strip-err { color: #F08A8A; font-size: 12px; }

.status {
  flex: 0 0 auto;
  padding: 6px 10px;
  font-size: 12px;
  line-height: 1.4;
  color: #94A3B8;
  background: #1E293B;
  border-bottom: 1px solid #334155;
}
.status.ok   { color: #6FCFA4; }
.status.warn { color: #E5B562; }
.status.err  { color: #F08A8A; }

/* AG Studio sizes itself to its container, so the container needs a real height. */
.stage { position: relative; flex: 1 1 auto; min-height: 0; display: flex; }
#studio-root { flex: 1 1 auto; min-height: 0; min-width: 0; }

/* --- saved reports list ----------------------------------------------------- */
.panel {
  position: absolute;
  top: 6px;
  right: 8px;
  width: 460px;
  max-width: calc(100% - 16px);
  max-height: calc(100% - 12px);
  display: flex;
  flex-direction: column;
  background: #1E293B;
  border: 1px solid #334155;
  border-radius: 8px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, .45);
  z-index: 50;
}
.panel[hidden] { display: none; }
.panel-head { padding: 8px; border-bottom: 1px solid #334155; }
.panel-head input { width: 100%; }
.panel-body { overflow: auto; }
.empty { padding: 16px 12px; color: #94A3B8; font-size: 13px; }

.item { padding: 9px 12px; border-bottom: 1px solid #263449; }
.item:last-child { border-bottom: 0; }
.item.current { background: #1B2B44; box-shadow: inset 3px 0 0 #3B82F6; }
.item-top { display: flex; align-items: center; gap: 8px; }
.item-name {
  flex: 1 1 auto;
  min-width: 0;
  text-align: left;
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  color: #E2E8F0;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.item-name:hover { color: #93C5FD; text-decoration: underline; }
.item-actions { display: flex; gap: 4px; flex: 0 0 auto; }
.item-meta { margin-top: 3px; font-size: 12px; color: #94A3B8; }
.item-edit { display: flex; gap: 6px; align-items: center; margin-top: 6px; }
.item-edit input { flex: 1 1 auto; min-width: 0; }
.item-warn { margin-top: 6px; font-size: 12px; color: #E5B562; }
.item-err { margin-top: 4px; font-size: 12px; color: #F08A8A; }

/* AG Studio 3.0.0 draws the magnifier inside its search boxes but leaves the
   text at the plain 8px inset, so the placeholder runs under the icon. */
#studio-root .ag-text-field-input-wrapper:has(.ag-input-field-search-icon) .ag-input-field-input {
  padding-left: 30px;
}

