function darkTheme() {
  try {
    return agStudio.studioTheme.withParams(DARK);
  } catch (e) {
    console.warn('dark theme failed, falling back to default', e);
    return undefined;
  }
}

function statusLine(model) {
  var n = rowsOf(model).length.toLocaleString();
  var mode = modeOf(model) === 'view' ? 'view mode (read only)' : 'edit mode';
  // The licence note only matters once someone has entered a key: without one
  // Studio runs as a trial with every feature, and saying so is just noise.
  return n + ' rows · ' + mode + (appliedKey ? ' · ' + licenceNote : '') + (lintMsg ? ' · ' + lintMsg : '');
}

function showStatusLine(model) {
  setStatus(statusLine(model), lintMsg ? 'warn' : 'ok');
}

// --- Ask UBM chart checks ----------------------------------------------------
// An Ask UBM source is not linked to the others (its columns are named by the
// AI), and Studio does not refuse a widget that mixes them: it quietly shows
// the same total on every row. Page filters on the other sources do not reach
// it either. Neither can be blocked, so both are called out in the status line.
var lintMsg = '';

function fieldIds(node, out) {
  if (Array.isArray(node)) node.forEach(function (n) { fieldIds(n, out); });
  else if (node && typeof node === 'object') {
    if (typeof node.id === 'string') out.push(node.id);
    for (var k in node) if (k !== 'id') fieldIds(node[k], out);
  }
  return out;
}

function sourceOf(id) {
  if (id.indexOf('.') > 0) return id.split('.')[0];
  return MEASURES.some(function (m) { return m.id === id; }) ? 'measure' : '';
}

function askLint(state) {
  if (!state || !Array.isArray(state.pages)) return '';
  var mixed = [], askWidgets = 0, filtered = false;
  state.pages.forEach(function (p) {
    var widgets = (p && p.widgets) || {};
    Object.keys(widgets).forEach(function (wid) {
      var w = widgets[wid] || {};
      var srcs = {};
      fieldIds(w.dataMapping, []).forEach(function (id) { var s = sourceOf(id); if (s) srcs[s] = true; });
      var names = Object.keys(srcs);
      var ask = names.filter(function (n) { return n.indexOf('ask_') === 0; });
      if (ask.length) askWidgets++;
      if (ask.length && names.length > 1) {
        mixed.push('"' + ((w.format && w.format.title && w.format.title.text) || wid) + '"');
      }
    });
    if (p && p.filter && Array.isArray(p.filter.page) && p.filter.page.length) filtered = true;
  });
  if (mixed.length) {
    return 'WRONG NUMBERS in ' + mixed.join(', ') + ': an Ask UBM chart can only use its own source\'s fields';
  }
  if (askWidgets && filtered) return 'page filters do not apply to Ask UBM charts';
  return '';
}

// Measures Studio cannot build from its own field list. A ratio has to be
// summed first and divided after, at whatever grouping the widget uses:
// averaging per-row ratios gives every small bill the same weight as a large
// one. This is the Rank of Locations unit cost on the Analytics page,
// charges ÷ consumption per group, left blank (not 0) where there is no
// consumption. Units differ per utility, so it only means something with a
// single utility type filtered.
function ratio(top, bottom) {
  var t = { id: 'monthly_usage.' + top, aggregation: 'sum' };
  var b = { id: 'monthly_usage.' + bottom, aggregation: 'sum' };
  return {
    operator: 'if',
    inputs: [
      { operator: 'greaterThan', inputs: [b, { type: 'number', value: 0 }] },
      { operator: 'divide', inputs: [t, b] },
      { type: 'number', value: null }
    ]
  };
}

// Unit costs are small ($0.12/kWh is typical), so whole dollars would show
// most of them as $0.
var UNIT_COST_FORMAT = {
  format: new Intl.NumberFormat('en-US', {
    style: 'currency', currency: 'USD', minimumFractionDigits: 3, maximumFractionDigits: 4
  })
};

var MEASURES = [
  {
    id: 'unit_cost',
    name: 'Unit Cost ($/unit)',
    description: 'Total charges ÷ total consumption. Filter to one utility type: units differ between utilities.',
    format: 'currencyFormat',
    formatOptions: UNIT_COST_FORMAT,
    isMeasure: true,
    expression: ratio('total_charges', 'consumption')
  },
  {
    id: 'unit_cost_mmbtu',
    name: 'Unit Cost ($/mmBTU)',
    description: 'Total charges ÷ total mmBTU. Comparable across energy utilities; filter out water and sewer, whose charges carry no mmBTU.',
    format: 'currencyFormat',
    formatOptions: UNIT_COST_FORMAT,
    isMeasure: true,
    expression: ratio('total_charges', 'consumption_mmbtu')
  },
  // Analytics shows one month's load factor per location (the oldest it
  // meets), which is not an aggregate Studio can express. The mean of the
  // monthly values is the closest honest summary at any grouping.
  {
    id: 'load_factor_avg',
    name: 'Load Factor (%)',
    description: 'Average of the monthly load factors. Filter to ELECTRIC: other utilities have none.',
    isMeasure: true,
    format: 'decimalFormat',
    formatOptions: { format: new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) },
    expression: { id: 'demand.load_factor', aggregation: 'avg' }
  }
];

// --- data model --------------------------------------------------------------
// Two fact sources with different grains: monthly usage (per meter and
// account) and demand (per bill item group). A chart that takes its sites from
// one and its numbers from the other used to show the overall figure on every
// bar, because Studio had no way to relate them; a date filter on one did not
// reach the other either. So location, month and utility are lifted into
// shared sources, each linked one-to-many to both facts, and the facts' own
// copies of those columns are hidden. Hidden fields still resolve, so reports
// saved before this keep working.
var LOCATION_COLS = ['location_id', 'location_description', 'city', 'state', 'building_type'];
var SHARED_COLS = LOCATION_COLS.concat(['time_period', 'utility_type']);

// The two queries return months in different shapes (a timestamp from one, a
// date from the other), and a join needs identical values.
function monthKey(v) {
  return v == null ? v : String(v).slice(0, 10);
}

function withMonthKey(rows) {
  return rows.map(function (r) {
    var c = {};
    for (var k in r) c[k] = r[k];
    c.time_period = monthKey(r.time_period);
    return c;
  });
}

function distinctBy(rowSets, key, cols) {
  var seen = {}, out = [];
  rowSets.forEach(function (rows) {
    rows.forEach(function (r) {
      var k = r[key];
      if (k == null || seen[k]) return;
      seen[k] = true;
      var d = {};
      cols.forEach(function (c) { d[c] = r[c] == null ? null : r[c]; });
