}

// Declaring any field switches Studio's inference off for the whole source,
// so every column is declared, with the format Studio would have inferred
// from the first value that is not blank, and the shared columns hidden.
var ISO_DATE = /^\d{4}-\d{2}-\d{2}(T[\d:.]+(Z|[+-]\d{2}:?\d{2})?)?$/;

function formatOf(rows, col) {
  for (var i = 0; i < rows.length; i++) {
    var v = rows[i][col];
    if (v == null || v === '') continue;
    if (typeof v === 'number') return 'decimalFormat';
    if (typeof v === 'boolean') return 'booleanFormat';
    if (typeof v === 'string' && ISO_DATE.test(v)) return 'dateFormat';
    return 'textFormat';
  }
  return 'textFormat';
}

function label(col) {
  return col.charAt(0).toUpperCase() + col.slice(1);
}

function fieldsFor(rows) {
  var cols = {};
  rows.slice(0, 500).forEach(function (r) { for (var k in r) cols[k] = true; });
  return Object.keys(cols).map(function (c) {
    var f = { id: c, name: label(c), format: formatOf(rows, c) };
    if (SHARED_COLS.indexOf(c) >= 0) f.hide = true;
    return f;
  });
