  var base = slug(dot > 0 ? name.slice(0, dot) : name);

  // A widget the user actually named keeps that name; only the defaults are
  // swapped out, so renaming a widget in Studio still renames its export.
  if (GENERIC_NAMES[base]) {
    base = String(type || '').indexOf('image/') === 0 ? 'chart' : slug(SOURCE_LABEL);
  }

  var who = lastModel && lastModel.customerName ? slug(lastModel.customerName) : '';
  return [base, who, todayStamp()].filter(Boolean).join('-') + (ext ? '.' + ext : '');
}

// Chart images never touch createObjectURL — ag-charts hands the anchor a
// base64 data: URL straight from canvas.toDataURL() — so that shape is read
// off the href directly.
function dataUrlPayload(href) {
  if (href.slice(0, 5) !== 'data:') return null;
  var comma = href.indexOf(',');
  if (comma < 0) return null;
  var meta = href.slice(5, comma);
  if (meta.indexOf(';base64') < 0) return null;
  return { type: meta.split(';')[0] || 'application/octet-stream', url: href };
}

function interceptDownloads() {
  if (window.URL && typeof URL.createObjectURL === 'function') {
    var mint = URL.createObjectURL.bind(URL);
    URL.createObjectURL = function (obj) {
      var url = mint(obj);
      if (typeof Blob !== 'undefined' && obj instanceof Blob) {
        blobsByUrl[url] = obj;
        // Studio also mints blob URLs for chart images it never downloads, so
        // let them go again rather than hold every Blob for the life of the page.
        setTimeout(function () { delete blobsByUrl[url]; }, 60000);
      }
      return url;
    };
  }

  // Grid exports dispatch a synthetic click with bubbles: false and chart
  // images call anchor.click(), which does bubble. The capture phase runs from
  // the document down to the target either way, so it catches both.
  document.addEventListener('click', function (ev) {
    var anchor = (ev.target && ev.target.closest) ? ev.target.closest('a[download]') : null;
    if (!anchor) return;
    var href = anchor.getAttribute('href') || '';
    var name = anchor.getAttribute('download') || 'export';

    var blob = blobsByUrl[href];
    if (blob) {
      ev.preventDefault();
      ev.stopPropagation();
      exportBlob(exportFileName(name, blob.type), blob);
      return;
    }

    var payload = dataUrlPayload(href);
    if (payload) {
      ev.preventDefault();
      ev.stopPropagation();
      sendExport(exportFileName(name, payload.type), payload.type, payload.url);
    }
  }, true);
}

function exportBlob(fileName, blob) {
  // Checked here as well as in sendExport: blob.size is free, whereas finding
  // out after readAsDataURL means holding the whole export in memory twice
  // over just to reject it.
  if (blob.size > MAX_EXPORT_BYTES) { tooBig(blob.size); return; }
  setStatus('Preparing ' + fileName + '…');
  var reader = new FileReader();
  reader.onerror = function () { setStatus('Could not read the export.', 'err'); };
  reader.onload = function () {
    // readAsDataURL gives "data:<type>;base64,<payload>"; Appsmith's download()
    // wants the bare payload, with the type passed alongside it.
    var url = String(reader.result || '');
    if (url.indexOf(',') < 0) { setStatus('Could not encode the export.', 'err'); return; }
    sendExport(fileName, blob.type || 'application/octet-stream', url);
  };
  reader.readAsDataURL(blob);
}

function tooBig(bytes) {
  setStatus('That export is ' + (bytes / 1048576).toFixed(1) + 'MB, over the ' +
            (MAX_EXPORT_BYTES / 1048576) + 'MB this widget can hand to Appsmith. Narrow it and retry.', 'err');
}

// Appsmith's download() has a base64 branch that pulls "data:<type>;base64,..."
// over XHR, and this instance's CSP lists no data: scheme in connect-src, so
// that branch dies with a Network Error before anything is written. Handing it
// the whole data: URL instead lands in its plain branch, where downloadjs
// decodes the payload locally with atob and never touches the network.
function sendExport(fileName, fileType, dataUrl) {
  var bytes = Math.floor((dataUrl.length - dataUrl.indexOf(',') - 1) * 3 / 4);
  if (bytes > MAX_EXPORT_BYTES) { tooBig(bytes); return; }
  try {
    appsmith.triggerEvent('onExportFile', {
      fileName: fileName,
      fileType: fileType,
      fileData: dataUrl
    });
    setStatus('Sent ' + fileName + ' to the browser.', 'ok');
    setTimeout(function () { showStatusLine(lastModel); }, 4000);
  } catch (e) {
    console.error('handing the export to Appsmith failed', e);
    setStatus('Could not hand the export to Appsmith — see console.', 'err');
  }
}

// --- saved reports ---------------------------------------------------------
// Reports are kept in the database and shared by everyone who views the
// customer. The list, the open report and a busy message come in through the
// model; the layout goes out only as an event, at the moment Save is pressed.
// It never travels through appsmith.updateModel: the widget's `model` is a meta
// property whose default is `defaultModel`, so it is reset whenever any
// dependency re-evaluates (picking a customer, flipping the mode switch), which
// once dropped the state silently before Save could read it.
var DEFAULT_MAX_STATE_CHARS = 1000000;
var baselineKey = null;   // the layout as last opened or saved, see compareKey
var baselineUntil = 0;    // Studio settles its own state just after start-up
var pendingKey = null;    // the layout of a save that has not come back yet
var lastJustSaved = '';
var lastBusy = '';
var dirty = false;
var listOpen = false;
var listSig = '';
var editingId = '';
var editDraft = '';
var editError = '';
var removingId = '';
var confirmAction = null;

function reportsOf(model) { return (model && Array.isArray(model.reports)) ? model.reports : []; }
function currentOf(model) { return (model && model.current && model.current.id) ? model.current : null; }
function busyOf(model) { return (model && model.busy) ? String(model.busy) : ''; }

function mk(tag, cls, text) {
  var n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

function button(label, cls, disabled, onClick) {
  var b = mk('button', 'btn ' + (cls || ''), label);
  b.type = 'button';
  b.disabled = !!disabled;
  b.onclick = onClick;
  return b;
}

// The layout without what is not worth keeping: the AI assistant's threads
// (no AI is configured on this page) and each page's selection, which only
// records what was clicked last.
function cleanState(state) {
  if (!state || typeof state !== 'object' || !Array.isArray(state.pages)) return null;
  var copy = JSON.parse(JSON.stringify(state));
  delete copy.ai;
  copy.pages.forEach(function (p) { if (p) delete p.selection; });
  return copy;
}

function hasWidgets(state) {
  return !!state && state.pages.some(function (p) {
    return p && p.widgets && Object.keys(p.widgets).length > 0;
  });
}

// What counts as an unsaved change: the clean layout, ignoring which side
// panels are open, since that is chrome rather than report.
function compareKey(state) {
  var c = cleanState(state);
  if (!c) return '';
  delete c.panels;
  return JSON.stringify(c);
}

function currentState() {
  if (api && typeof api.getState === 'function') {
    try {
      var s = api.getState();
      if (s) return s;
    } catch (e) { /* fall back to the last state Studio reported */ }
  }
  return liveState;
}

// A message that goes back to the usual status line after a few seconds.
function flashStatus(text, kind) {
  setStatus(text, kind);
  setTimeout(function () { if (api) showStatusLine(lastModel); }, 6000);
}

function updateDirty() {
  var key = api ? compareKey(currentState()) : '';
  // Until Studio has settled after a build, what it reports is the layout as
  // opened, not an edit.
  if (key !== '' && (baselineKey === null || Date.now() < baselineUntil)) baselineKey = key;
  dirty = baselineKey !== null && key !== '' && key !== baselineKey;
  var lint = api ? askLint(currentState()) : '';
  if (lint !== lintMsg) {
    lintMsg = lint;
    showStatusLine(lastModel);
  }
  renderBar();
}

function fmtWhen(v) {
  if (!v) return '';
  var d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleString(undefined, {
    day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'
  });
}

// Who saved a report and when, plus who created it if someone else did.
function whoWhen(r) {
  var by = r.updatedBy || r.createdBy || 'unknown';
  var line = 'Saved by ' + by + ' · ' + fmtWhen(r.updatedAt || r.createdAt);
  if (r.createdBy && r.createdBy !== by) line += ' · created by ' + r.createdBy;
  return line;
}

function renderBar() {
  var m = lastModel;
  var cur = currentOf(m);
  var busy = busyOf(m);
  var name = el('rep-name');
  if (!name) return;
  name.textContent = cur ? cur.name : 'Unsaved report';
  name.className = 'rep-name' + (cur ? '' : ' unsaved');
  name.title = cur ? cur.name : '';
  el('rep-dirty').hidden = !dirty;
  el('rep-meta').textContent = cur ? whoWhen(cur) : '';
  el('rep-busy').textContent = busy;
  el('rep-count').textContent = '(' + reportsOf(m).length + ')';
  el('btn-save').disabled = !!busy || !api;
  el('btn-save').title = cur ? 'Save changes to "' + cur.name + '"' : 'Name this report and save it';
  el('btn-saveas').disabled = !!busy || !api;
  el('btn-new').disabled = !!busy;
  el('name-ok').disabled = !!busy;
  el('confirm-yes').disabled = !!busy;
}

// --- name form, confirmation ------------------------------------------------
function openNameForm(mode) {
  hideConfirm();
  closeList();
  var cur = currentOf(lastModel);
  var input = el('name-input');
  input.value = (mode === 'saveAs' && cur) ? cur.name + ' (copy)' :
                (!cur && lastModel && lastModel.suggestedName) ? String(lastModel.suggestedName) : '';
  el('name-err').textContent = '';
  el('name-form').hidden = false;
  input.focus();
  input.select();
}

function closeNameForm() {
  el('name-form').hidden = true;
  el('name-err').textContent = '';
}

function nameTaken(name, exceptId) {
  var k = String(name).trim().toLowerCase();
  return reportsOf(lastModel).some(function (r) {
    return r.id !== exceptId && String(r.name || '').trim().toLowerCase() === k;
  });
}

// The database enforces the same rules (one live report per name and
// customer, ignoring case); checking here first keeps the message next to the
// box being typed in.
function checkName(name, exceptId) {
  var n = String(name || '').trim();
  if (!n) return 'Give the report a name.';
  if (n.length > 120) return 'Keep the name to 120 characters or fewer.';
  if (nameTaken(n, exceptId)) {
    return 'A report called "' + n + '" already exists for this customer. ' +
           'Pick another name, or open that report and press Save.';
  }
  return '';
}

function submitNameForm() {
  var name = el('name-input').value.trim();
  var err = checkName(name, '');
  if (err) { el('name-err').textContent = err; return; }
  if (sendSave('saveAs', name)) closeNameForm();
}

function showConfirm(text, yesLabel, fn) {
  closeNameForm();
  closeList();
  confirmAction = fn;
  el('confirm-text').textContent = text;
  el('confirm-yes').textContent = yesLabel;
  el('confirm-strip').hidden = false;
}

function hideConfirm() {
  confirmAction = null;
  el('confirm-strip').hidden = true;
}

// Run fn straight away, or after a confirmation when it would throw away
// changes that were never saved.
function guardDiscard(doing, yesLabel, fn) {
  updateDirty();
  if (!dirty) { fn(); return; }
  var cur = currentOf(lastModel);
  showConfirm('Discard your unsaved changes' + (cur ? ' to "' + cur.name + '"' : '') + ' and ' + doing + '?',
              yesLabel, fn);
}

// --- actions -----------------------------------------------------------------
function sendSave(mode, name) {
  var clean = cleanState(currentState());
  if (!hasWidgets(clean)) {
    flashStatus('Nothing to save yet — add a chart or table first.', 'warn');
    return false;
  }
  // The state goes into the SQL text, so a runaway layout is refused here
  // rather than as a vague database error.
  var json = JSON.stringify(clean);
  var max = Number(lastModel && lastModel.maxStateChars) || DEFAULT_MAX_STATE_CHARS;
  if (json.length > max) {
    flashStatus('This layout is ' + Math.ceil(json.length / 1024) + ' KB, over the ' +
                Math.floor(max / 1024) + ' KB a saved report can hold. Remove some widgets or pages and retry.', 'err');
    return false;
  }
  pendingKey = compareKey(clean);
  try {
    appsmith.triggerEvent('onSaveReport', {
      saveMode: mode,
      reportName: name || '',
      reportState: clean,
      reportCust: lastModel && lastModel.customerId
    });
    return true;
  } catch (e) {
    pendingKey = null;
    console.error('handing the report to Appsmith failed', e);
    setStatus('Could not save the report — see console.', 'err');
    return false;
  }
}

function onSaveClick() {
  var cur = currentOf(lastModel);
  if (!cur) { openNameForm('save'); return; }
  closeNameForm();
  hideConfirm();
  sendSave('save', cur.name);
}

function onNewClick() {
  guardDiscard('start a blank report', 'Discard and start new', function () {
    hideConfirm();
    closeList();
    appsmith.triggerEvent('onNewReport', {});
  });
}

function openReport(r) {
  guardDiscard('open "' + r.name + '"', 'Discard and open', function () {
    hideConfirm();
    closeList();
    appsmith.triggerEvent('onOpenReport', { reportId: r.id });
  });
}

function submitRename(r) {
  var name = editDraft.trim();
  if (name === r.name) { editingId = ''; renderList(); return; }
  var err = checkName(name, r.id);
  if (err) { editError = err; renderList(); return; }
  appsmith.triggerEvent('onRenameReport', { reportId: r.id, reportName: name });
  editingId = '';
  editError = '';
  renderList();
}

function submitRemove(r) {
  appsmith.triggerEvent('onRemoveReport', { reportId: r.id });
  removingId = '';
  renderList();
}

// --- saved reports list ------------------------------------------------------
function openList() {
  hideConfirm();
  closeNameForm();
  listOpen = true;
  listSig = '';
  el('list-panel').hidden = false;
  renderList();
  el('list-filter').focus();
  // Pick up reports colleagues saved, renamed or removed since the list loaded.
  try { appsmith.triggerEvent('onRefreshReports', {}); } catch (e) { /* the list on hand still works */ }
}

function closeList() {
  listOpen = false;
  editingId = '';
  editError = '';
  removingId = '';
  el('list-panel').hidden = true;
}

function shownReports() {
  var q = el('list-filter').value.trim().toLowerCase();
  return reportsOf(lastModel).filter(function (r) {
    return !q || String(r.name || '').toLowerCase().indexOf(q) >= 0;
  });
}

function itemFor(r, cur, busy) {
  var item = mk('div', 'item' + (cur && cur.id === r.id ? ' current' : ''));
  var top = mk('div', 'item-top');
  var name = mk('button', 'item-name', r.name);
  name.type = 'button';
  name.title = 'Open "' + r.name + '"';
  name.disabled = !!busy;
  name.onclick = function () { openReport(r); };
  top.appendChild(name);

  var actions = mk('div', 'item-actions');
  actions.appendChild(button('Open', 'small', busy, function () { openReport(r); }));
  actions.appendChild(button('Rename', 'small', busy, function () {
    editingId = r.id; editDraft = r.name; editError = ''; removingId = '';
    renderList();
  }));
  actions.appendChild(button('Remove', 'small', busy, function () {
    removingId = r.id; editingId = '';
    renderList();
  }));
  top.appendChild(actions);
  item.appendChild(top);
  item.appendChild(mk('div', 'item-meta', whoWhen(r)));

  if (editingId === r.id) {
    var edit = mk('div', 'item-edit');
    var input = mk('input');
    input.type = 'text';
    input.maxLength = 120;
    input.value = editDraft;
    input.setAttribute('data-rename', '1');
    input.oninput = function () { editDraft = input.value; };
    input.onkeydown = function (ev) {
      if (ev.key === 'Enter') submitRename(r);
      else if (ev.key === 'Escape') { editingId = ''; editError = ''; renderList(); }
    };
    edit.appendChild(input);
    edit.appendChild(button('Save name', 'small primary', busy, function () { submitRename(r); }));
    edit.appendChild(button('Cancel', 'small', false, function () { editingId = ''; editError = ''; renderList(); }));
    item.appendChild(edit);
    if (editError) item.appendChild(mk('div', 'item-err', editError));
  }

  if (removingId === r.id) {
    item.appendChild(mk('div', 'item-warn', 'Remove "' + r.name + '" for everyone who views this customer?'));
    var confirm = mk('div', 'item-edit');
    confirm.appendChild(button('Remove', 'small danger', busy, function () { submitRemove(r); }));
    confirm.appendChild(button('Cancel', 'small', false, function () { removingId = ''; renderList(); }));
    item.appendChild(confirm);
  }
  return item;
}

function renderList() {
  if (!listOpen) return;
  var reports = reportsOf(lastModel);
  var cur = currentOf(lastModel);
  var busy = busyOf(lastModel);
  var shown = shownReports();
  // Typing in the rename box is not part of the signature, so a keystroke
  // never rebuilds the list under the cursor.
  var sig = JSON.stringify([shown, cur && cur.id, editingId, removingId, editError, busy, reports.length]);
  if (sig === listSig) return;
  listSig = sig;

  var body = el('list-body');
  body.innerHTML = '';
  if (!reports.length) {
    body.appendChild(mk('div', 'empty', 'No saved reports for this customer yet. Build a layout and press Save.'));
    return;
  }
  if (!shown.length) {
    body.appendChild(mk('div', 'empty', 'No report name contains "' + el('list-filter').value.trim() + '".'));
    return;
  }
  shown.forEach(function (r) { body.appendChild(itemFor(r, cur, busy)); });

  var renaming = body.querySelector('input[data-rename]');
  if (renaming) {
    renaming.focus();
    renaming.setSelectionRange(renaming.value.length, renaming.value.length);
  }
}

// Called with every model. A save counts as done when the open report comes
// back stamped justSaved; a save that ends without one (refused, or someone
// else saved first) leaves the unsaved-changes marker as it was.
function onReportsModel(model) {
  var cur = currentOf(model);
  var busy = busyOf(model);
  var just = (cur && cur.justSaved) ? String(cur.justSaved) : '';
  if (pendingKey !== null) {
    if (just && just !== lastJustSaved) {
      baselineKey = pendingKey;
      pendingKey = null;
    } else if (!busy && lastBusy) {
      pendingKey = null;
    }
  }
  lastJustSaved = just;
  lastBusy = busy;
  updateDirty();
  renderList();
}

function wireBar() {
  el('btn-save').onclick = onSaveClick;
  el('btn-saveas').onclick = function () { openNameForm('saveAs'); };
  el('btn-new').onclick = onNewClick;
  el('btn-list').onclick = function () { if (listOpen) closeList(); else openList(); };
  el('name-ok').onclick = submitNameForm;
  el('name-cancel').onclick = closeNameForm;
  el('name-input').onkeydown = function (ev) {
    if (ev.key === 'Enter') submitNameForm();
    else if (ev.key === 'Escape') closeNameForm();
  };
  el('confirm-yes').onclick = function () {
    var fn = confirmAction;
    hideConfirm();
    if (fn) fn();
  };
  el('confirm-no').onclick = hideConfirm;
  el('list-filter').oninput = function () { renderList(); };
  // Enter opens the report when the name typed matches exactly one.
  el('list-filter').onkeydown = function (ev) {
    if (ev.key === 'Escape') { closeList(); return; }
    if (ev.key !== 'Enter') return;
    var shown = shownReports();
    if (shown.length === 1) openReport(shown[0]);
  };
  // Studio does not report every change (setState, for one, stays silent), so
  // the unsaved-changes marker is also rechecked on a slow beat. getState on a
  // layout this size costs well under a millisecond.
  setInterval(function () { if (api) updateDirty(); }, 1500);

  // A click anywhere outside the list closes it.
  document.addEventListener('mousedown', function (ev) {
    if (!listOpen) return;
    if (el('list-panel').contains(ev.target) || el('btn-list').contains(ev.target)) return;
    closeList();
  });
}

