function darkTheme() {
  try {
    return agStudio.studioTheme.withParams(DARK);
  } catch (e) {
    console.warn('dark theme failed, falling back to default', e);
    return undefined;
  }
}

function statusLine(model) {
  var n = rowsOf(model).length.toLocaleString();
  var mode = modeOf(model) === 'view' ? 'view mode (read only)' : 'edit mode';
  // The licence note only matters once someone has entered a key: without one
  // Studio runs as a trial with every feature, and saying so is just noise.
  return n + ' rows · ' + mode + (appliedKey ? ' · ' + licenceNote : '') + (lintMsg ? ' · ' + lintMsg : '');
}

function showStatusLine(model) {
  setStatus(statusLine(model), lintMsg ? 'warn' : 'ok');
}

// --- Ask UBM chart checks ----------------------------------------------------
// An Ask UBM source is not linked to the others (its columns are named by the
// AI), and Studio does not refuse a widget that mixes them: it quietly shows
// the same total on every row. Page filters on the other sources do not reach
// it either. Neither can be blocked, so both are called out in the status line.
var lintMsg = '';

function fieldIds(node, out) {
  if (Array.isArray(node)) node.forEach(function (n) { fieldIds(n, out); });
  else if (node && typeof node === 'object') {
    if (typeof node.id === 'string') out.push(node.id);
    for (var k in node) if (k !== 'id') fieldIds(node[k], out);
  }
  return out;
}

function sourceOf(id) {
  if (id.indexOf('.') > 0) return id.split('.')[0];
  return MEASURES.some(function (m) { return m.id === id; }) ? 'measure' : '';
}

function askLint(state) {
  if (!state || !Array.isArray(state.pages)) return '';
  var mixed = [], askWidgets = 0, filtered = false;
  state.pages.forEach(function (p) {
    var widgets = (p && p.widgets) || {};
    Object.keys(widgets).forEach(function (wid) {
      var w = widgets[wid] || {};
      var srcs = {};
      fieldIds(w.dataMapping, []).forEach(function (id) { var s = sourceOf(id); if (s) srcs[s] = true; });
      var names = Object.keys(srcs);
      var ask = names.filter(function (n) { return n.indexOf('ask_') === 0; });
      if (ask.length) askWidgets++;
      if (ask.length && names.length > 1) {
        mixed.push('"' + ((w.format && w.format.title && w.format.title.text) || wid) + '"');
      }
    });
    if (p && p.filter && Array.isArray(p.filter.page) && p.filter.page.length) filtered = true;
  });
  if (mixed.length) {
    return 'WRONG NUMBERS in ' + mixed.join(', ') + ': an Ask UBM chart can only use its own source\'s fields';
  }
  if (askWidgets && filtered) return 'page filters do not apply to Ask UBM charts';
  return '';
}

// Measures Studio cannot build from its own field list. A ratio has to be
// summed first and divided after, at whatever grouping the widget uses:
// averaging per-row ratios gives every small bill the same weight as a large
// one. This is the Rank of Locations unit cost on the Analytics page,
// charges ÷ consumption per group, left blank (not 0) where there is no
// consumption. Units differ per utility, so it only means something with a
// single utility type filtered.
function ratio(top, bottom) {
  var t = { id: 'monthly_usage.' + top, aggregation: 'sum' };
  var b = { id: 'monthly_usage.' + bottom, aggregation: 'sum' };
  return {
    operator: 'if',
    inputs: [
      { operator: 'greaterThan', inputs: [b, { type: 'number', value: 0 }] },
      { operator: 'divide', inputs: [t, b] },
      { type: 'number', value: null }
    ]
  };
}

// Unit costs are small ($0.12/kWh is typical), so whole dollars would show
// most of them as $0.
var UNIT_COST_FORMAT = {
  format: new Intl.NumberFormat('en-US', {
    style: 'currency', currency: 'USD', minimumFractionDigits: 3, maximumFractionDigits: 4
  })
};

var MEASURES = [
  {
    id: 'unit_cost',
    name: 'Unit Cost ($/unit)',
    description: 'Total charges ÷ total consumption. Filter to one utility type: units differ between utilities.',
    format: 'currencyFormat',
    formatOptions: UNIT_COST_FORMAT,
    isMeasure: true,
    expression: ratio('total_charges', 'consumption')
  },
  {
    id: 'unit_cost_mmbtu',
    name: 'Unit Cost ($/mmBTU)',
    description: 'Total charges ÷ total mmBTU. Comparable across energy utilities; filter out water and sewer, whose charges carry no mmBTU.',
    format: 'currencyFormat',
    formatOptions: UNIT_COST_FORMAT,
    isMeasure: true,
    expression: ratio('total_charges', 'consumption_mmbtu')
  },
  // Analytics shows one month's load factor per location (the oldest it
  // meets), which is not an aggregate Studio can express. The mean of the
  // monthly values is the closest honest summary at any grouping.
  {
    id: 'load_factor_avg',
    name: 'Load Factor (%)',
    description: 'Average of the monthly load factors. Filter to ELECTRIC: other utilities have none.',
    isMeasure: true,
    format: 'decimalFormat',
    formatOptions: { format: new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) },
    expression: { id: 'demand.load_factor', aggregation: 'avg' }
  }
];

// --- data model --------------------------------------------------------------
// Two fact sources with different grains: monthly usage (per meter and
// account) and demand (per bill item group). A chart that takes its sites from
// one and its numbers from the other used to show the overall figure on every
// bar, because Studio had no way to relate them; a date filter on one did not
// reach the other either. So location, month and utility are lifted into
// shared sources, each linked one-to-many to both facts, and the facts' own
// copies of those columns are hidden. Hidden fields still resolve, so reports
// saved before this keep working.
var LOCATION_COLS = ['location_id', 'location_description', 'city', 'state', 'building_type'];
var SHARED_COLS = LOCATION_COLS.concat(['time_period', 'utility_type']);

// The two queries return months in different shapes (a timestamp from one, a
// date from the other), and a join needs identical values.
function monthKey(v) {
  return v == null ? v : String(v).slice(0, 10);
}

function withMonthKey(rows) {
  return rows.map(function (r) {
    var c = {};
    for (var k in r) c[k] = r[k];
    c.time_period = monthKey(r.time_period);
    return c;
  });
}

function distinctBy(rowSets, key, cols) {
  var seen = {}, out = [];
  rowSets.forEach(function (rows) {
    rows.forEach(function (r) {
      var k = r[key];
      if (k == null || seen[k]) return;
      seen[k] = true;
      var d = {};
      cols.forEach(function (c) { d[c] = r[c] == null ? null : r[c]; });
      out.push(d);
    });
  });
  return out;
}

// Declaring any field switches Studio's inference off for the whole source,
// so every column is declared, with the format Studio would have inferred
// from the first value that is not blank, and the shared columns hidden.
var ISO_DATE = /^\d{4}-\d{2}-\d{2}(T[\d:.]+(Z|[+-]\d{2}:?\d{2})?)?$/;

function formatOf(rows, col) {
  for (var i = 0; i < rows.length; i++) {
    var v = rows[i][col];
    if (v == null || v === '') continue;
    if (typeof v === 'number') return 'decimalFormat';
    if (typeof v === 'boolean') return 'booleanFormat';
    if (typeof v === 'string' && ISO_DATE.test(v)) return 'dateFormat';
    return 'textFormat';
  }
  return 'textFormat';
}

function label(col) {
  return col.charAt(0).toUpperCase() + col.slice(1);
}

function fieldsFor(rows) {
  var cols = {};
  rows.slice(0, 500).forEach(function (r) { for (var k in r) cols[k] = true; });
  return Object.keys(cols).map(function (c) {
    var f = { id: c, name: label(c), format: formatOf(rows, c) };
    if (SHARED_COLS.indexOf(c) >= 0) f.hide = true;
    return f;
  });
}

function link(id, dim, fact, col) {
  return {
    id: id,
    source: { tableId: dim, fieldId: col },
    target: { tableId: fact, fieldId: col },
    type: 'one-to-many'
  };
}

function dataModel(model) {
  var usage = withMonthKey(rowsOf(model));
  var demand = withMonthKey(demandRowsOf(model));
  var facts = demand.length ? [usage, demand] : [usage];
  var factIds = demand.length ? ['monthly_usage', 'demand'] : ['monthly_usage'];

  var sources = [{
    id: 'monthly_usage',
    name: (model && model.customerName ? model.customerName + ' — ' : '') + SOURCE_LABEL,
    description: 'Monthly billed usage and charges per meter and account. Group by the Location, Month and Utility sources.',
    data: usage,
    fields: fieldsFor(usage)
  }];
  if (demand.length) {
    sources.push({
      id: 'demand',
      name: 'Demand & Load Factor',
      description: 'Billed demand (kW) and load factor (%) per location, month, utility and bill type, from the bill calculations. ' +
                   'Load_factor with aggregation Last gives the value the Analytics Rank of Locations view shows.',
      data: demand,
      fields: fieldsFor(demand)
    });
  }
  // Each Ask UBM chart is a source of its own. Its columns are whatever the AI
  // named them, so it is not linked to the shared sources: build widgets for
  // it from its own fields only.
  askOf(model).forEach(function (a) {
    if (!a.rows || !a.rows.length) return;
    sources.push({
      id: 'ask_' + a.key,
      name: 'Ask UBM: ' + (a.title || a.question || a.key),
      description: (a.question ? 'Answer to "' + a.question + '". ' : '') +
                   'Re-run with current data each time the report opens. Use only this source\'s fields in its widgets.',
      data: a.rows
    });
  });
  sources.push(
    { id: 'location', name: 'Location', description: 'Every location in either source.',
      data: distinctBy(facts, 'location_id', LOCATION_COLS) },
    { id: 'month', name: 'Month', description: 'Every billing month in either source.',
      data: distinctBy(facts, 'time_period', ['time_period']) },
    { id: 'utility', name: 'Utility', description: 'Every utility type in either source.',
      data: distinctBy(facts, 'utility_type', ['utility_type']) }
  );

  var relationships = [];
  factIds.forEach(function (f) {
    relationships.push(
      link('location_' + f, 'location', f, 'location_id'),
      link('month_' + f, 'month', f, 'time_period'),
      link('utility_' + f, 'utility', f, 'utility_type')
    );
  });

  return {
    sources: sources,
    relationships: relationships,
    // One widget mixing measures from both facts finds several join paths
    // between them and inflates its numbers. Refusing to run it is better than
    // a chart that looks right and is not.
    options: { fanout: { warning: true, execute: 'prevent' } },
    // A measure on the demand source cannot be defined until it is loaded.
    expressions: demand.length ? MEASURES : MEASURES.filter(function (m) { return m.id !== 'load_factor_avg'; })
  };
}

function buildStudio(model) {
  var root = el('studio-root');
  if (!root) return;
  var rows = rowsOf(model);

  if (api && typeof api.destroy === 'function') {
    try { api.destroy(); } catch (e) { /* already gone */ }
  }
  api = null;
  liveState = null;
  baselineKey = null;
  root.innerHTML = '';

  if (rows.length === 0) {
    setStatus('No rows returned for this customer.', 'warn');
    renderBar();
    return;
  }

  var props = {
    mode: modeOf(model),
    theme: darkTheme(),
    data: dataModel(model),
    dataOptions: { maxExportRows: -1 },
    onStudioReady: function () {
      showStatusLine(model);
      // Whatever Studio shows once it is ready is the layout as opened. It may
      // still tidy its state for a moment after, so updates in that window
      // move the baseline instead of reading as unsaved changes.
      baselineKey = null;
      baselineUntil = Date.now() + 1500;
      updateDirty();
    },
    onErrorRaised: function (ev) {
      console.error('AG Studio error', ev);
      setStatus('Studio error: ' + ((ev && ev.message) || 'see console'), 'err');
    },
    // Held locally only — see the saved reports section for why this never
    // goes into the widget model.
    onStateUpdated: function (ev) {
      if (ev && ev.state) {
        liveState = ev.state;
      } else if (api && typeof api.getState === 'function') {
        try { liveState = api.getState(); } catch (e) { /* leave the last good state */ }
      }
      updateDirty();
    }
  };

  if (model && model.savedState) props.initialState = model.savedState;

  try {
    api = agStudio.createStudio(root, props);
    setStatus('Starting AG Studio…');
    renderBar();
  } catch (e) {
    console.error(e);
    setStatus('createStudio failed: ' + (e && e.message), 'err');
  }
}

function render(model) {
  if (!window.agStudio || !agStudio.createStudio) {
    setStatus('AG Studio bundle did not load — check the CDN script tag.', 'err');
    return;
  }
  lastModel = model;

  // A key only reaches Studio through createStudio, so a new one forces a rebuild.
  var keyChanged = applyLicense(model);

  var sig = dataSignature(model);
  var stateKey = Number(model && model.stateKey) || 0;
  var mode = modeOf(model);

  // stateKey only moves when a saved report is opened or the workspace is
  // cleared. Saving does not touch it, so a save never tears down the workspace.
  if (sig === lastDataSig && stateKey === lastStateKey && !keyChanged) {
    if (api && mode !== lastMode) {
      lastMode = mode;
      try {
        api.setProperty('mode', mode);
        showStatusLine(model);
      } catch (e) {
        console.warn('mode switch failed, rebuilding', e);
        buildStudio(model);
      }
    }
    return;
  }

  lastDataSig = sig;
  lastStateKey = stateKey;
  lastMode = mode;
  buildStudio(model);
}

// The bundle is large; poll briefly for the global before first render.
function whenReady(model, tries) {
  if (window.agStudio && agStudio.createStudio) { render(model); return; }
  if (tries <= 0) {
    setStatus('Timed out waiting for the AG Studio bundle (~5MB). Reload the page.', 'err');
    return;
  }
  setStatus('Loading AG Studio bundle…');
  setTimeout(function () { whenReady(model, tries - 1); }, 250);
}

interceptDownloads();
wireBar();

appsmith.onReady(function () {
  lastModel = appsmith.model;
  onReportsModel(appsmith.model);
  whenReady(appsmith.model, 160);

  appsmith.onModelChange(function (model) {
    lastModel = model;
    onReportsModel(model);
    if (window.agStudio && agStudio.createStudio) render(model);
  });
});
